import{At as e,Pt as t,Ut as n,gt as r,ht as i,mt as a,n as o,pt as s,ut as c}from"./chunks/framework.BrKcMR_c.js";var l=JSON.parse(`{"title":"ADR-0073: Owner-managed command whitelist","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/0073-owner-managed-command-whitelist.md","filePath":"adrs/0073-owner-managed-command-whitelist.md","lastUpdated":1789092097000}`),u={name:`adrs/0073-owner-managed-command-whitelist.md`};function d(o,l,u,d,f,p){let m=t(`Term`);return e(),s(`div`,null,[l[9]||=c(`h1`,{id:`adr-0073-owner-managed-command-whitelist`,tabindex:`-1`},[i(`ADR-0073: Owner-managed command whitelist `),c(`a`,{class:`header-anchor`,href:`#adr-0073-owner-managed-command-whitelist`,"aria-label":`Permalink to “ADR-0073: Owner-managed command whitelist”`},`​`)],-1),l[10]||=c(`p`,null,`Status: Accepted · 2026-09-08`,-1),l[11]||=c(`h2`,{id:`context`,tabindex:`-1`},[i(`Context `),c(`a`,{class:`header-anchor`,href:`#context`,"aria-label":`Permalink to “Context”`},`​`)],-1),c(`p`,null,[l[1]||=i(`The user wants practical shell permissions for `,-1),r(m,{term:`tool`},{default:n(()=>[...l[0]||=[i(`tools`,-1)]]),_:1}),l[2]||=i(` such as npm and Git, including custom scripts, dependency installs and remote access. Fixed argument/subcommand lists would impede normal project work. ADR-0070 already provides executable-wide approval but only adds entries through a running command's dialog.`,-1)]),l[12]||=c(`h2`,{id:`decision`,tabindex:`-1`},[i(`Decision `),c(`a`,{class:`header-anchor`,href:`#decision`,"aria-label":`Permalink to “Decision”`},`​`)],-1),c(`p`,null,[l[4]||=i(`The `,-1),r(m,{term:`pen`},{default:n(()=>[...l[3]||=[i(`Pen`,-1)]]),_:1}),l[5]||=i(`'s Command permissions section supports Add tool, Edit, Remove and Reset. An owner can enter an executable name or path, check the resolved executable, select one chat or all chats in the Pen, and separately allow requested network access. All arguments and child processes remain covered by the executable grant within the existing Pen confinement. No npm-script or Git-subcommand allowlist is introduced.`,-1)]),l[13]||=c(`p`,null,`Checking resolves metadata and validates the workspace without running the executable or authorizing network access. Save revalidates the reviewed executable and physical workspace and rejects stale permission revisions. Changed binaries, replaced folders, removed entries and resets cannot be overwritten by an older review. Validation errors remain separate from persistence authority failures. Executable paths are optional stored metadata so older entries remain readable.`,-1),c(`p`,null,[l[7]||=i(`Refining ADR-0070's exact network-mode matching, a network-enabled grant also authorizes offline calls of that executable. An offline grant does not authorize network requests. The launched command's network flag still determines its actual sandbox: allowing a tool to request networking never silently gives an offline command networking. `,-1),r(m,{term:`judas`},{default:n(()=>[...l[6]||=[i(`JUDAS`,-1)]]),_:1}),l[8]||=i(` can deny networking regardless of the whitelist. Network permission covers outbound connections generally, not selected domains.`,-1)]),l[14]||=a(`<p>Permissions are additive: a Pen-wide grant applies to every chat, and a chat-only grant cannot narrow it. The editor explains this. Owner edits replace their selected entry and merge equivalent executable/scope entries. Existing action dialogs continue to add grants. Removing grants affects future launches; stopping a running command remains a separate action.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><p>Users can allow npm, Git and custom tools without enumerating project scripts. Dependency installation is supported with network approval. The UI shows resolved paths and scope to make the granted capability reviewable. A command or network capability does not instruct the agent to publish changes; the user&#39;s task remains authoritative. Existing filesystem restrictions, credential isolation and non-interactive command limits remain.</p><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to “Alternatives considered”">​</a></h2><ul><li>Enumerate npm scripts and Git subcommands: rejected by the user as too restrictive.</li><li>Infer network permission from executable names: child programs and custom scripts make this unreliable.</li><li>Run a program to validate it: introduces unnecessary side effects during configuration.</li><li>Treat a network-enabled grant as requiring network on every call: incorrectly couples capability with execution mode.</li></ul>`,5)])}var f=o(u,[[`render`,d]]);export{l as __pageData,f as default};